    return isOneOf(Name, {"spin_lock", "spin_lock_irqsave", "spin_lock_bh", "spin_lock_irq"});
  }
  // Fallback to textual check
  const Expr *E = Call.getOriginExpr();
  if (!E) return false;
  return ExprHasName(E, "spin_lock_irqsave", C) ||
         ExprHasName(E, "spin_lock_irq", C) ||
         ExprHasName(E, "spin_lock_bh", C) ||
         ExprHasName(E, "spin_lock", C);
}

static bool isLockRelease(const CallEvent &Call, CheckerContext &C) {
  if (const IdentifierInfo *ID = Call.getCalleeIdentifier()) {
    StringRef Name = ID->getName();
    return isOneOf(Name, {"spin_unlock", "spin_unlock_irqrestore", "spin_unlock_bh", "spin_unlock_irq"});
  }
  const Expr *E = Call.getOriginExpr();
  if (!E) return false;
  return ExprHasName(E, "spin_unlock_irqrestore", C) ||
         ExprHasName(E, "spin_unlock_irq", C) ||
         ExprHasName(E, "spin_unlock_bh", C) ||
         ExprHasName(E, "spin_unlock", C);
}

// Resolve a stable object key for a pointer/object expression: an explicit
// address-of maps to the referenced region, a pointer lvalue maps to the
// object whose pointer it stores, and an opaque pointer value maps to the
// symbolic region of that value. Using the same key for uses inside a
// critical section and for a later store pairs the object with its
// protecting lock across the unlock.
static const MemRegion *getRegionKeyFromExpr(const Expr *E, CheckerContext &C) {
  if (!E)
    return nullptr;

  ProgramStateRef State = C.getState();
  SVal V = State->getSVal(E, C.getLocationContext());

  // Address-of (e.g. &hsotg->lock): the referenced region names the object.
  if (const auto *UO = dyn_cast<UnaryOperator>(E->IgnoreParens()))
    if (UO->getOpcode() == UO_AddrOf)
      if (const MemRegion *R = V.getAsRegion())
        return R->getBaseRegion();

  // Pointer lvalue (e.g. the base of an arrow access): the stored pointer
  // value designates the shared object.
  if (auto MRV = V.getAs<loc::MemRegionVal>()) {
    const auto *SlotR = dyn_cast_or_null<SubRegion>(MRV->getRegion());
    if (!SlotR)
      return nullptr;
    QualType SlotTy = SlotR->getValueType();
    if (SlotTy->isPointerType()) {
      SVal PV = State->getRawSVal(*MRV, SlotTy);
      if (const MemRegion *R = PV.getAsRegion())
        return R->getBaseRegion();
      if (SymbolRef Sym = PV.getAsSymbol())
        return C.getSValBuilder().getSymbolManager().getSymbolicRegion(Sym);
      return nullptr;
    }
    return SlotR->getBaseRegion();
  }

  // Loaded pointer value (e.g. a call argument): region or symbolic region.
  if (const MemRegion *R = V.getAsRegion())
    return R->getBaseRegion();
  if (SymbolRef Sym = V.getAsSymbol())
    return C.getSValBuilder().getSymbolManager().getSymbolicRegion(Sym);
  return nullptr;
}

static const MemRegion *getLockRegionFromCall(const CallEvent &Call, CheckerContext &C) {
  if (Call.getNumArgs() < 1)
    return nullptr;
  const Expr *Arg0 = Call.getArgExpr(0);
  if (!Arg0)
    return nullptr;
  return getRegionKeyFromExpr(Arg0, C);
}

static ProgramStateRef addHeldLock(ProgramStateRef State, const MemRegion *Lock, CheckerContext &C) {
  if (!Lock) return State;
  LockSet Cur = State->get<HeldLocks>();
  LockSet::Factory &F = State->get_context<HeldLocks>();
  Cur = F.add(Cur, Lock);
  State = State->set<HeldLocks>(Cur);
  return State;
}

static ProgramStateRef removeHeldLock(ProgramStateRef State, const MemRegion *Lock) {
  if (!Lock) return State;
  LockSet Cur = State->get<HeldLocks>();
  LockSet::Factory &F = State->get_context<HeldLocks>();
  Cur = F.remove(Cur, Lock);
  State = State->set<HeldLocks>(Cur);
  return State;
}

static bool lockSetContains(const LockSet &S, const MemRegion *R) {
  for (auto It = S.begin(); It != S.end(); ++It) {
    if (*It == R)
      return true;
  }
  return false;
}

static bool objSetContains(const ObjSet &S, const MemRegion *R) {
  for (auto It = S.begin(); It != S.end(); ++It) {
    if (*It == R)
      return true;
  }
  return false;
}

// Record that "ObjR" is used while holding each lock in HeldLocks.
static ProgramStateRef recordObjUseUnderHeldLocks(ProgramStateRef State,
                                                  const Expr *ArgE,
                                                  CheckerContext &C) {
  if (!ArgE)
    return State;
  LockSet Locks = State->get<HeldLocks>();
  if (Locks.isEmpty())
    return State;

  const MemRegion *ObjR = getRegionKeyFromExpr(ArgE, C);
  if (!ObjR)
    return State;

  ObjSet::Factory &OF = State->get_context<ObjSetTrait>();
  for (auto LI = Locks.begin(); LI != Locks.end(); ++LI) {
    const MemRegion *LockR = *LI;
    if (!LockR) continue;
    const ObjSet *CurPtr = State->get<LockToObjSetMap>(LockR);
    ObjSet Cur = CurPtr ? *CurPtr : OF.getEmptySet();
    if (!objSetContains(Cur, ObjR)) {
      Cur = OF.add(Cur, ObjR);
      State = State->set<LockToObjSetMap>(LockR, Cur);
    }
  }
  return State;
}

static bool isZeroSVal(SVal V) {
  if (auto CI = V.getAs<nonloc::ConcreteInt>())
    return CI->getValue() == 0;
  if (auto LCI = V.getAs<loc::ConcreteInt>())
    return LCI->getValue() == 0;
  return false;
}

static bool isPointerFieldAssignmentToNull(const Stmt *S, SVal Loc, SVal Val,
                                           CheckerContext &C,
                                           const BinaryOperator *&OutBO,
                                           const MemberExpr *&OutME) {
  OutBO = nullptr;
  OutME = nullptr;

  const auto *BO = dyn_cast_or_null<BinaryOperator>(S);
  if (!BO || !BO->isAssignmentOp())
    return false;

  const Expr *LHS = BO->getLHS()->IgnoreParenCasts();
  const auto *ME = dyn_cast<MemberExpr>(LHS);
  if (!ME)
    return false;

  // We focus on pointer field like obj->field.
  if (!ME->isArrow())
    return false;

  QualType FieldTy = ME->getType();
  if (FieldTy.isNull() || !FieldTy->isPointerType())
    return false;

  bool IsNull = isZeroSVal(Val);
  if (!IsNull) {
    // Try evaluate RHS constant int == 0
    llvm::APSInt IntV;
    if (EvaluateExprToInt(IntV, BO->getRHS(), C))
      IsNull = (IntV == 0);
  }
  if (!IsNull)
    return false;

  OutBO = BO;
  OutME = ME;
  return true;
}

static bool isSharedPointerSlot(const Expr *BaseE) {
  // The written object is shared with other contexts only when the pointer
  // that designates it comes from a caller (parameter) or global storage;
  // purely local pointers cannot race with lock-holding readers.
  if (!BaseE)
    return false;
  const auto *DRE = dyn_cast<DeclRefExpr>(BaseE->IgnoreParenImpCasts());
  if (!DRE)
    return false;
  const auto *VD = dyn_cast<VarDecl>(DRE->getDecl());
  if (!VD)
    return false;
  return isa<ParmVarDecl>(VD) || VD->hasGlobalStorage();
}

static const MemRegion *getBaseObjectRegionFromLHS(const BinaryOperator *BO,
                                                   CheckerContext &C) {
  if (!BO) return nullptr;
  const auto *ME = dyn_cast<MemberExpr>(BO->getLHS()->IgnoreParenCasts());
  if (!ME) return nullptr;
  return getRegionKeyFromExpr(ME->getBase(), C);
}

